interface ResearchSubEntry {
  code: string;      // 子条目编码（如 BB.1.3-①）
  name: string;      // 子条目名称（与需求演示侧边栏一致）
  parent: string;    // 父表单编码（BB.1.3）
  sheetName: string; // 对应 sheet 的 name（适配器返回值）
}

const SUB_FORM_ENTRIES: ResearchSubEntry[] = RESEARCH_SUB_ENTRIES;

const SUB_ENTRY_BY_CODE: Record<string, ResearchSubEntry> = Object.fromEntries(
  SUB_FORM_ENTRIES.map((e) => [e.code, e]),
);

// 依据字段注册表按表单编码聚合字段
const FIELDS_BY_FORM: Record<string, BudgetFieldDef[]> = {};
for (const f of BUDGET_FIELD_REGISTRY) {
  (FIELDS_BY_FORM[f.formCode] ||= []).push(f);
}

