  'BAA.6': '不涉及财报转换（仅参数：BAA.6.a 场所基本信息维护 / BAA.6.b 年度租赁面积维护（含单价）/ BAA.6.c 场所法人比例查看 / BAA.6.e 租赁折现率维护，为 BB.4.2.b 内部职场租赁与 BB.4.2.b.1 内部职场租赁·财务视角提供面积、占比、单价与折现率参数，不生成会计分录）。',
