  'BB.5.1': { applies: ['HR按法人×部门×费用项目（销售/研发/管理/制造费用/实际发放）填报薪酬预算；财务视角另含自制在建工程列，体现 BB.4.1 资本化人工导致的雇员费用减少'], notApplies: ['非薪酬经营费用（属 BB.5.2）'] },
