// 字段说明按「激活 TAB 编码 → 父编码回退」取数；BB.1.1 的合同编码/合同名称已直接登记在共享字段注册表中，本页不再做列序补丁。
export function fieldsForDisplayFromTs(formCode: string): BudgetFieldDef[] {
  let fields = FIELDS_BY_FORM[formCode] ?? [];
  // TAB 编码（如 BB.1.2.a、BB.4.X.A）无直接字段登记时，回退父编码（BB.1.2、BB.4.X）
  if (fields.length === 0) {
    const parent = formCode.replace(/\.([A-Za-z])$/, '');
    if (parent !== formCode) fields = FIELDS_BY_FORM[parent] ?? [];
  }
  // 父编码无直接字段登记时，聚合其子编码(.a/.b/.c)字段（按 BUDGET_FIELD_REGISTRY 原始登记顺序）
  if (fields.length === 0) {
    const prefix = formCode + '.';
    fields = BUDGET_FIELD_REGISTRY.filter((f) => f.formCode.startsWith(prefix));
  }
  const financeFields = financeResearchFields(formCode, fields);
  if (financeFields) return financeFields;
  // BB.4.X 资本性支出汇总表：3 个 TAB 字段就地声明，按 TAB 拆分（不回写注册表）
  if (formCode === 'BB.4.X.A') {
    return [
      {
        formCode,
        fieldCode: 'mfgExpenseDep',
        fieldName: '制造费用折旧',
        dataType: 'number',
        inputMode: '系统带出',
        required: true,
        source: 'BB.4.X.A 折旧费用汇总表',
        remark: '直接引用附表 A (BB.4.X.A) 制造费用折旧小计，供利润表制造费用科目入账；增量折旧含 BB.4.5（含来源=代采购转入的代采购转入资产折旧）',
      },
      {
        formCode,
        fieldCode: 'rndExpenseDep',
        fieldName: '研发费用折旧与摊销',
        dataType: 'number',
        inputMode: '系统带出',
        required: true,
        source: 'BB.4.X.A 折旧费用汇总表',
        remark: '直接引用附表 A (BB.4.X.A) 研发费用折旧与摊销小计，供利润表 6603 科目入账；增量折旧含 BB.4.5（含来源=代采购转入的代采购转入资产折旧）',
      },
      {
        formCode,
        fieldCode: 'adminExpenseDep',
        fieldName: '管理费用折旧与摊销',
        dataType: 'number',
        inputMode: '系统带出',
        required: true,
        source: 'BB.4.X.A 折旧费用汇总表',
        remark: '直接引用附表 A (BB.4.X.A) 管理费用折旧与摊销小计，供利润表 6602 科目入账；增量折旧含 BB.4.5（含来源=代采购转入的代采购转入资产折旧）',
      },
      {
        formCode,
        fieldCode: 'salesExpenseDep',
        fieldName: '销售费用折旧与摊销',
        dataType: 'number',
        inputMode: '系统带出',
        required: true,
        source: 'BB.4.X.A 折旧费用汇总表',
        remark: '直接引用附表 A (BB.4.X.A) 销售费用折旧与摊销小计，供利润表 6601 科目入账；增量折旧含 BB.4.5（含来源=代采购转入的代采购转入资产折旧）',
      },
    ];
  }
  return fields;
}

/**
 * ② 字段与值说明取数（含 XML 文字源覆盖）：
 * 结构化元数据（inputMode/required/dataType/dropdown）仍取 TS 注册表，仅把「文字」
 * （字段名称 / 数据来源 / 其他说明）换成 src/data/texts/{code}.xml 的登记值；
 * 该表未登记 XML 时（getFormText → undefined）完全等价于原 TS 行为。
 */
export function fieldsForDisplay(formCode: string): BudgetFieldDef[] {
  const base = fieldsForDisplayFromTs(formCode);
  const ft = getFormText(formCode);
  if (!ft || ft.fields.length === 0) return base;

  // 同名 fieldCode 在 TS 登记里可能重复（如 BB.4.X 的 assetCategory）：
  // XML 与 TS 按「同 code 出现次序」一一对应，保证逐行文字与迁移前完全一致。
  const queues = new Map<string, { name: string; display: string; source: string; remark: string; idx: number }[]>();
  ft.fields.forEach((x, idx) => {
    const item = { name: x.name, display: x.display, source: x.source, remark: x.remark, idx };
    const q = queues.get(x.code);
    if (q) q.push(item);
    else queues.set(x.code, [item]);
  });
  const consumed = new Set<number>();
  const merged = base.map((f) => {
    const x = queues.get(f.fieldCode)?.shift();
    if (!x) return f;
    consumed.add(x.idx);
    return {
      ...f,
      fieldName: x.display || x.name || f.fieldName,
      source: x.source || f.source,
      remark: x.remark || f.remark,
    };
  });

  // XML 声明了、TS 注册表没有的字段：按 XML 补一行（结构元数据用默认值），保持 XML 原始次序
  const extra: BudgetFieldDef[] = ft.fields
    .filter((_x, idx) => !consumed.has(idx))
    .map((x) => ({
      formCode,
      fieldCode: x.code,
      fieldName: x.display || x.name,
      dataType: 'string',
      inputMode: '手工',
      required: false,
      source: x.source,
      remark: x.remark,
    }));

  return extra.length === 0 ? merged : [...merged, ...extra];
}
